#include <bits/stdc++.h>

using namespace std;

using ii = pair<int,int>;

constexpr int MAX_D = 11;
constexpr int MAX_N = 1000;
constexpr int MAX_E = 100100;
constexpr int MAX_FLOW_VAL = (1<<29);

struct Edge {
    int v;
    int f;
    int c;
    int next;
};

Edge E[2 * MAX_E];
int head[MAX_N], ptr[MAX_N], lvl[MAX_N], Q[MAX_N];
int num_edges, num_nodes, source, sink, qf, qb;

inline void init_graph(int n, int s, int d) {
    num_nodes = n;
    source = s;
    sink = d;
    num_edges = 2;
    memset(head, 0, sizeof(int) * (n + 1));
}

inline void add_edge(int u, int v, int cap) {
    E[num_edges] = {v, 0, cap, head[u]};
    head[u] = num_edges++;
    E[num_edges] = {u, 0, 0, head[v]};
    head[v] = num_edges++;
}

inline bool bfs_level() {
    memset(lvl, 0, sizeof(int) * (num_nodes + 1));
    qf = qb = 0;
    Q[qb++] = source;
    lvl[source] = 1;
    while (qf < qb && !lvl[sink]) {
        int u = Q[qf++];
        for (int e = head[u]; e; e = E[e].next) {
            int v = E[e].v;
            if (!lvl[v] && E[e].f < E[e].c) {
                lvl[v] = lvl[u] + 1;
                Q[qb++] = v;
            }
        }
    }
    return lvl[sink];
}

inline int dfs(int u, int f) {
    if (u == sink) return f;
    for (int &e = ptr[u]; e; e = ptr[u] = E[e].next) {
        int v = E[e].v;
        if (lvl[u] < lvl[v] && E[e].f < E[e].c &&
            (f = dfs(v, min(f, E[e].c - E[e].f)))) {
            E[e].f += f;
            E[e ^ 1].f -= f;
            return f;
        }
    }
    return 0;
}

inline int dinic() {
    int ret = 0, df;
    while (bfs_level()) {
        copy(head, head + num_nodes + 1, ptr);
        while ((df = dfs(source, MAX_FLOW_VAL))) ret += df;
    }
    return ret;
}

int R;
string B1[MAX_D], B2[MAX_D];

int DR[4] = {0, 1, 0, -1};
int DC[4] = {1, 0, -1, 0};

inline bool valid(int i, int j) {
    return i >= 0 && j >= 0 && i < R && j < R && B1[i][j] != 'Y' && B1[i][j] != 'Z';
}

int d[2][MAX_D][MAX_D];

inline void bfs_dist(int si, int sj, int idx) {
    memset(d[idx], 0, sizeof(d[idx]));
    d[idx][si][sj] = 1;
    queue<ii> q;
    q.push({si, sj});
    while (!q.empty()) {
        auto [i, j] = q.front(); q.pop();
        if (idx == 1 && d[0][i][j] && d[0][i][j] <= d[1][i][j]) continue;
        for (int k = 0; k < 4; ++k) {
            int ni = i + DR[k], nj = j + DC[k];
            if (valid(ni, nj) && !d[idx][ni][nj]) {
                d[idx][ni][nj] = d[idx][i][j] + 1;
                q.push({ni, nj});
            }
        }
    }
}

int id[2][MAX_D][MAX_D];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T; cin >> R >> T;

    int zi = 0, zj = 0;
    int node_cnt = 0;

    for (int i = 0; i < R; ++i) {
        cin >> B1[i];
        for (int j = 0; j < R; ++j) {
            if (B1[i][j] == 'Z') { zi = i; zj = j; }
            else if (B1[i][j] != 'Y') {
                node_cnt++;
                id[0][i][j] = node_cnt;
            }
        }
    }

    for (int i = 0; i < R; ++i) {
        cin >> B2[i];
        for (int j = 0; j < R; ++j) {
            if (B2[i][j] != 'Y' && B2[i][j] != 'Z') {
                node_cnt++;
                id[1][i][j] = node_cnt;
            }
        }
    }

    node_cnt++;
    int src = 0, dst = node_cnt;

    init_graph(node_cnt, src, dst);

    for (int i = 0; i < R; ++i) {
        for (int j = 0; j < R; ++j) {
            if (B1[i][j] != 'Z' && B1[i][j] != 'Y') {
                add_edge(src, id[0][i][j], B1[i][j] - '0');
                add_edge(id[1][i][j], dst, B2[i][j] - '0');
            }
        }
    }

    bfs_dist(zi, zj, 0);

    for (int i = 0; i < R; ++i) {
        for (int j = 0; j < R; ++j) {
            if (B1[i][j] > '0' && B1[i][j] <= '9') {
                bfs_dist(i, j, 1);
                for (int ii = 0; ii < R; ++ii) {
                    for (int jj = 0; jj < R; ++jj) {
                        if (B2[ii][jj] > '0' && B2[ii][jj] <= '9') {
                            if (d[1][ii][jj] &&
                                (!d[0][ii][jj] || d[0][ii][jj] >= d[1][ii][jj]) &&
                                d[1][ii][jj] - 1 <= T) {
                                add_edge(id[0][i][j], id[1][ii][jj], MAX_FLOW_VAL);
                            }
                        }
                    }
                }
            }
        }
    }

    cout << dinic() << '\n';
}
